#!/usr/bin/env python3
"""Generate assets/project-*.svg: one clickable row per project in the README.

Each row copies a row of the website's `ls projects/` terminal (site.css .term__row):
the number and arrow in champagne, the name in the text color, Geist Mono embedded
as base64 because GitHub's <img> loads no outside fonts. The rows come in one after
another like the site's listing (360 ms fade and 6 px rise, 260 ms apart).
Each row is its own image so README.md can link it to its repo.

Run from the repo root:  python3 .github/scripts/projects.py
"""
import base64
from html import escape
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]

PROJECTS = [          # (number, name); the links live in README.md
    ('01', 'Synthia'),
    ('02', 'Autexa'),
    ('03', 'FIRST Robotics 7102'),
    ('04', '6-DOF robotic arm'),
    ('~', 'dotfiles'),
]
ROW_EVERY = 260       # page.js rowEveryMs
START = 300           # first row
W, H = 860, 52

font = base64.b64encode((ROOT / 'assets/fonts/geist-mono-400.woff2').read_bytes()).decode()

for i, (num, name) in enumerate(PROJECTS):
    svg = f'''<svg xmlns="http://www.w3.org/2000/svg" width="{W}" height="{H}" viewBox="0 0 {W} {H}" role="img" aria-label="{escape(num)} {escape(name)}">
  <!-- generated by .github/scripts/projects.py, edit that file instead -->
  <style>
    @font-face {{ font-family: 'Geist Mono'; font-weight: 400; src: url(data:font/woff2;base64,{font}) format('woff2'); }}
    text {{ font-family: 'Geist Mono',ui-monospace,SFMono-Regular,Menlo,Consolas,'Liberation Mono',monospace; font-size: 16px; }}
    .n, .go {{ fill: #D9C7A0; }}
    .name {{ fill: #F3F1EC; }}
    .row {{ opacity: 0; animation: row 360ms cubic-bezier(.16,1,.3,1) {START + i * ROW_EVERY}ms forwards; }}
    @keyframes row {{ from {{ opacity: 0; transform: translateY(6px); }} to {{ opacity: 1; transform: translateY(0); }} }}
    @media (prefers-reduced-motion: reduce) {{ .row {{ opacity: 1; animation: none; }} }}
  </style>
  <g class="row">
    <rect x="0.5" y="0.5" width="{W - 1}" height="{H - 1}" rx="10" fill="#141517" stroke="rgba(243,241,236,.12)"/>
    <text class="n" x="24" y="31.5">{escape(num)}</text>
    <text class="name" x="72" y="31.5">{escape(name)}</text>
    <text class="go" x="{W - 24}" y="31.5" text-anchor="end">→</text>
  </g>
</svg>
'''
    slug = 'dotfiles' if num == '~' else num
    (ROOT / f'assets/project-{slug}.svg').write_text(svg, encoding='utf-8')
print(f'{len(PROJECTS)} rows')
